mapper.sql:
SELECT ci.id AS id, ci.create_user_id AS createUserId, ci.create_user_name AS createUserName, ci.create_time AS createTime, ci.update_user_id AS updateUserId, ci.update_user_name AS updateUserName, ci.update_time AS updateTime, ci.VERSION AS VERSION, ci.is_deleted AS isDeleted, ci.approve_status AS approveStatus, ci.code AS code, ci.service_provider_id AS serviceProviderId, ci.service_provider_name AS serviceProviderName, ci.approve_time AS approveTime, ci.approve_user_id AS approveUserId, ci.approve_user_name AS approveUserName, ci.type AS type, ci.effective_date AS effectiveDate, ci.expire_date AS expireDate, ci.status AS status, ci.disable AS disable FROM contract_info as ci WHERE ${params.sqlMap.default} AND ci.is_deleted = FALSE
and ci.id in
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ci.create_time DESC

mapper.select:
SELECT ci.status AS tabFlag, count(*) AS count FROM contract_info as ci WHERE ci.is_deleted=FALSE
${params.permissionSql}
GROUP BY ci.status

SELECT ci.id, ci.type, ci.service_provider_name as serviceProviderName, dict.name as typeName, ac.attach_url, ac.attach_name FROM contract_info AS ci INNER JOIN attachment AS ac ON ci.ID = ac.business_id AND ac.is_deleted = FALSE left join dict_basic as dict on ci.type = dict.value and dict.is_deleted = false and dict.status = true WHERE ${params.sqlMap.default} AND ci.is_deleted = FALSE
and ci.id in
#{id}
${params.permissionSql}
